test('sincroniza dos shows ficticios con alias Cali, conserva ID, fecha y precio al reintentar',async()=>{
 const previous=events,writes=calendarWrites,ids=['fixture-cali-venue','fixture-cali-private'];
 events=[...events,...ids.map((id,i)=>({id,summary:i?'PRIVADO-CALI':'CALI - LA COMADRE',start:{date:'2026-10-'+(16+i)},end:{date:'2026-10-'+(17+i)}}))];
 try{
  assert.equal((await api(ownerToken,'syncCalendar',{month:'2026-10'})).status,200);
  let feed=await api(ownerToken,undefined,{},'/api/crm?month=2026-10');const shows=feed.body.shows.filter(s=>s.municipality==='SANTIAGO DE CALI');assert.equal(shows.length,2);assert.deepEqual(shows.map(s=>s.showDate),['2026-10-16','2026-10-17']);assert.ok(shows.every(s=>s.sale===null));
  assert.equal((await update(shows[0].id,120000000)).status,200);await api(ownerToken,'syncCalendar',{month:'2026-10'});
  feed=await api(ownerToken,undefined,{},'/api/crm?month=2026-10');assert.equal(feed.body.shows.filter(s=>s.municipality==='SANTIAGO DE CALI').length,2);assert.equal(feed.body.shows.find(s=>s.id===shows[0].id).sale,120000000);assert.equal(calendarWrites,writes);
 }finally{events=previous;sql.prepare('DELETE FROM jac_crm_shows WHERE event_id IN (?,?)').run(...ids);}
});
