test('sincronización usa filas estables RAW, enlaces privados y estados; no duplica tras reintentar',async()=>{const p=payment(firstShow,30000000);assert.equal((await api(ownerToken,'addPayment',{record:p})).status,200);await Promise.all(deferred.splice(0));await api(ownerToken,'syncSheets');const row=sql.prepare('SELECT sequence FROM jac_crm_exports WHERE payment_id=?').get(p.id).sequence+1;assert.equal(cellRows.get(row)[3],30000000);assert.equal(cellRows.get(row)[4],'https://jhonalexcastano.com/api/crm/file?id='+p.id);assert.equal(cellRows.get(row)[5],'Registrado');const originalRow=sql.prepare('SELECT sequence FROM jac_crm_exports WHERE payment_id=?').get(firstPayment.id).sequence+1;assert.equal(cellRows.get(originalRow)[5],'Anulado');const total=cellRows.size,before=puts;await api(ownerToken,'syncSheets');assert.equal(cellRows.size,total);assert.equal(puts,before);assert.ok(calls.filter(c=>c.options.method==='PUT').every(c=>c.url.searchParams.get('valueInputOption')==='RAW'));});
test('resultado incierto de Google conserva abono y reintenta la misma celda sin agregar otra fila',async()=>{const p=payment(firstShow,20000000);let lost=false;googleHook=async(url,options)=>{if(url.pathname.endsWith('/values:batchUpdate')&&!lost){lost=true;for(const item of JSON.parse(options.body).data){puts++;const row=Number(item.range.match(/!A(\d+)/)[1]);cellRows.set(row,item.values[0]);}throw TypeError('Simulated lost Google response');}return null;};assert.equal((await api(ownerToken,'addPayment',{record:p})).status,200);await Promise.all(deferred.splice(0));googleHook=null;assert.equal(lost,true);const job=sql.prepare('SELECT * FROM jac_crm_exports WHERE payment_id=?').get(p.id);assert.ok(job.synced_version<job.version);const total=cellRows.size;assert.equal((await api(ownerToken,'syncSheets')).status,200);assert.equal(cellRows.size,total);assert.equal(sql.prepare('SELECT synced_version,version FROM jac_crm_exports WHERE payment_id=?').get(p.id).synced_version,job.version);});
test('una fila movida no sobrescribe otro abono y una sesión revocada antes del envío no publica datos',async()=>{const job=sql.prepare('SELECT * FROM jac_crm_exports ORDER BY sequence LIMIT 1').get(),row=job.sequence+1,old=cellRows.get(row);cellRows.set(row,[...old.slice(0,6),'foreign-record']);await update(firstShow,150000001);await Promise.all(deferred.splice(0));const before=puts;assert.equal((await api(ownerToken,'syncSheets')).status,409);assert.equal(puts,before);cellRows.set(row,old);assert.equal((await api(ownerToken,'syncSheets')).status,200);
 const id=crypto.randomUUID();account(id,'revoked-sheet@example.invalid',[m.ADMINISTRATOR_ROLE]);const token=await m.makeSession(id);sql.prepare('UPDATE jac_crm_exports SET version=version+1').run();googleHook=async url=>{if(url.href==='https://oauth2.googleapis.com/token')await m.revokeSession(token);return null;};const sent=puts;assert.equal((await api(token,'syncSheets')).status,403);googleHook=null;assert.equal(puts,sent);});
test('creación con respuesta perdida se recupera por appProperties; no crea otra hoja si no se confirma',async()=>{const original=await m.crmSheetsConfig();sql.prepare("UPDATE jac_crm_sheets SET spreadsheet_id='',spreadsheet_url='',file_request_id=?,creation_state='idle',version=version+1 WHERE id='jac'").run(crypto.randomUUID());sheetFile=null;let created;googleHook=async(url,options)=>{if(url.pathname==='/drive/v3/files'&&options.method==='POST'){sheetCreated++;const body=JSON.parse(options.body);created={id:'fixture-spreadsheet',mimeType:body.mimeType,appProperties:body.appProperties,webViewLink:'https://docs.google.com/spreadsheets/d/fixture-spreadsheet/edit'};sheetFile=created;throw TypeError('Simulated creation response lost');}return null;};assert.equal((await api(ownerToken,'createSheet')).status,502);googleHook=null;const before=sheetCreated;sheetFile=null;assert.equal((await api(ownerToken,'createSheet')).status,409);assert.equal(sheetCreated,before);sheetFile=created;assert.equal((await api(ownerToken,'createSheet')).status,200);assert.equal(sheetCreated,before);});
test('desconectar Sheets no revoca Google ni toca Gmail/Agenda, y el archivo se conserva',async()=>{const c=await m.crmSheetsConfig(),calendar=sql.prepare("SELECT credentials FROM payroll_calendar WHERE id='jac'").get().credentials;calls=[];assert.equal((await api(ownerToken,'disconnectSheets',{revision:c.version})).status,200);const next=await m.crmSheetsConfig();assert.equal(next.credentials,'');assert.equal(next.spreadsheet_id,c.spreadsheet_id);assert.equal(sql.prepare("SELECT credentials FROM payroll_calendar WHERE id='jac'").get().credentials,calendar);assert.equal(calls.length,0);});


test('cinco shows con precio llegan a una quincena móvil; conflicto CRM no guarda parcialmente',async()=>{
 const previous=events;events=['PEREIRA','MARQUETALIA','ARMENIA','MANIZALES','MEDELLIN'].map((name,i)=>({id:'nov-show-'+i,summary:name+' · noviembre ficticio',etag:'nov-'+i,start:{date:'2026-11-'+(17+i)},end:{date:'2026-11-'+(18+i)}}));
 try{await api(ownerToken,'syncCalendar',{month:'2026-11'});const shows=sql.prepare("SELECT * FROM jac_crm_shows WHERE show_date LIKE '2026-11-%' ORDER BY show_date").all();assert.equal(shows.length,5);for(let i=0;i<shows.length;i++)assert.equal((await update(shows[i].id,100000000+i*1000000)).status,200);
 const current=await m.readPayroll(),period={id:crypto.randomUUID(),start:'2026-11-16',end:'2026-11-30'};const preview=await api(ownerToken,'previewEdit',{version:current.version,edit:{kind:'period',record:period}},'/api/mobile/payroll');assert.equal(preview.status,200,preview.body.error);assert.equal(preview.body.detail.period.shows.length,5);assert.deepEqual(preview.body.detail.period.shows.map(s=>s.sale),[100000000,101000000,102000000,103000000,104000000]);
 batchHook=async rows=>{if(rows.some(r=>r.text.startsWith('UPDATE payroll_state SET'))){batchHook=null;sql.prepare('UPDATE jac_crm_shows SET version=version+1 WHERE id=?').run(shows[0].id);}};const conflict=await api(ownerToken,'edit',{version:current.version,edit:{kind:'period',record:period}},'/api/mobile/payroll');assert.equal(conflict.status,409);assert.equal((await m.readPayroll()).data.periods.length,current.data.periods.length);
 const saved=await api(ownerToken,'edit',{version:current.version,edit:{kind:'period',record:period}},'/api/mobile/payroll');assert.equal(saved.status,200,saved.body.error);assert.equal(saved.body.data.periods.find(p=>p.id===period.id).shows.length,5);
 const historical=structuredClone(saved.body.data);historical.periods[0].status='cerrada';historical.periods[0].snapshot={...m.calculate(saved.body.data,saved.body.data.periods[0]),closedAt:'2026-10-31T00:00:00Z',closedBy:'fixture'};const before=JSON.stringify(historical.periods[0]);const historicalNext=structuredClone(historical);await m.importCrmPeriods(historical,historicalNext);assert.equal(JSON.stringify(historicalNext.periods[0]),before);
 }finally{events=previous;batchHook=null;}
});

 test('diagnóstico Google distingue API desactivada y permiso sin exponer mensajes o tokens',()=>{const secret='token-private-never-display',disabled=m.crmGoogleError(403,{error:{message:secret,details:[{reason:'SERVICE_DISABLED',metadata:{service:'drive.googleapis.com',consumer:'projects/123456'}}]}},'www.googleapis.com');assert.equal(disabled.reason,'SERVICE_DISABLED');assert.ok(disabled.message.includes('Google Drive API'));assert.ok(disabled.message.includes('123456'));assert.ok(!JSON.stringify(disabled).includes(secret));const sheets=m.crmGoogleError(403,{error:{details:[{reason:'SERVICE_DISABLED',metadata:{service:'sheets.googleapis.com',consumer:secret}}]}},'sheets.googleapis.com');assert.ok(sheets.message.includes('Google Sheets API'));assert.equal(sheets.project,'');const scope=m.crmGoogleError(403,{error:{errors:[{reason:'insufficientPermissions'}]}},'www.googleapis.com');assert.equal(scope.reason,'ACCESS_TOKEN_SCOPE_INSUFFICIENT');assert.ok(scope.message.includes('Vuelve a autorizar'));assert.ok(!m.crmGoogleError(403,{error:{message:secret}},'www.googleapis.com').message.includes(secret));});
 test('Drive desactivada conserva autorización y no intenta crear una segunda hoja',async()=>{await oauthFinish(await oauthStart());sql.prepare("UPDATE jac_crm_sheets SET spreadsheet_id='',spreadsheet_url='',creation_state='idle'").run();const credentials=(await m.crmSheetsConfig()).credentials,created=sheetCreated;googleHook=async url=>url.pathname==='/drive/v3/files'?Response.json({error:{details:[{reason:'SERVICE_DISABLED',metadata:{service:'drive.googleapis.com',consumer:'projects/123456'}}]}},{status:403}):null;try{const r=await api(ownerToken,'createSheet');assert.equal(r.status,502);assert.ok(r.body.error.includes('Google Drive API está desactivada'));assert.equal(sheetCreated,created);assert.equal((await m.crmSheetsConfig()).credentials,credentials);assert.equal((await m.crmSheetsConfig()).creation_state,'idle');}finally{googleHook=null;}});

test('listado conserva hoy y próximos, cambia a medianoche Colombia y no elimina el historial',async()=>{
 const yesterday=crypto.randomUUID(),todayShow=crypto.randomUUID();for(const [id,date] of [[yesterday,'2026-10-17'],[todayShow,'2026-10-19']])sql.prepare('INSERT INTO jac_crm_shows(id,calendar_id,event_id,title,municipality,show_date,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(id,'fixture-calendar','date-'+id,'Show ficticio','PEREIRA',date,stamp,stamp);
 let dateToken;try{mock.timers.setTime(new Date('2026-10-19T04:59:59Z').getTime());dateToken=await m.makeSession(owner);let feed=await api(dateToken,undefined,{},'/api/crm?month=2026-10');assert.equal(feed.status,200);assert.equal(feed.body.today,'2026-10-18');assert.ok(feed.body.shows.some(s=>s.id===firstShow));assert.ok(feed.body.shows.some(s=>s.id===todayShow));assert.ok(!feed.body.shows.some(s=>s.id===yesterday));
 mock.timers.setTime(new Date('2026-10-19T05:00:00Z').getTime());feed=await api(dateToken,undefined,{},'/api/crm?month=2026-10');assert.equal(feed.body.today,'2026-10-19');assert.ok(!feed.body.shows.some(s=>s.id===firstShow));assert.ok(feed.body.shows.some(s=>s.id===todayShow));assert.ok(feed.body.shows.some(s=>s.showDate>'2026-10-19'));assert.ok(feed.body.shows.every(s=>s.showDate>='2026-10-19'));assert.ok((await api(dateToken,undefined,{},'/api/crm?month=2026-09')).body.shows.every(s=>s.showDate>='2026-10-19'));assert.equal((await api(dateToken,undefined,{},'/api/crm?month=2026-01')).body.shows.length,0);assert.ok((await api(dateToken,undefined,{},'/api/crm?month=2026-11')).body.shows.every(s=>s.showDate>='2026-11-01'));
 const historical=await api(dateToken,undefined,{},'/api/crm?payment='+firstPayment.id);assert.equal(historical.status,200);assert.equal(historical.body.show.id,firstShow);assert.ok(historical.body.payments.length>0);assert.ok(sql.prepare('SELECT id FROM jac_crm_shows WHERE id=?').get(yesterday));
 }finally{if(dateToken)await m.revokeSession(dateToken);mock.timers.setTime(fixtureClock);sql.prepare('DELETE FROM jac_crm_shows WHERE id IN (?,?)').run(yesterday,todayShow);}
});

