test('crear show y primer abono sincroniza solo el evento público; reintentos no duplican y no reescriben precio',async()=>{const first={amount:50000000,paymentDate:'2026-10-14',note:'Abono privado ficticio',files:[{filename:'Privado.pdf',data:proof}]},record=creationRecord({firstPayment:first}),before=calendarWrites;const result=await api(await m.makeSession(owner),'createShow',{record});assert.equal(result.status,200,result.body.error);assert.equal(result.body.show.sale,140000000);assert.equal(result.body.show.paid,50000000);assert.equal(result.body.show.balance,90000000);assert.equal(result.body.show.showDate,'2026-10-25');const raw=createdEvents.get('jac'+record.id.replaceAll('-',''));assert.equal(raw.start.dateTime,'2026-10-26T00:00:00.000Z');assert.equal(raw.start.timeZone,'America/Bogota');assert.equal(raw.description,record.event.description);assert.ok(!JSON.stringify(raw).includes(record.entrepreneur));assert.ok(!JSON.stringify(raw).includes(record.note));assert.ok(!JSON.stringify(raw).includes(first.note));assert.ok(!JSON.stringify(raw).includes('140000000'));assert.ok(!JSON.stringify(raw).includes(proof));assert.ok(calls.filter(c=>c.options.method==='POST'&&c.url.pathname.endsWith('/events')).every(c=>c.url.searchParams.get('sendUpdates')==='none'));assert.equal(calendarWrites,before+1);assert.equal((await api(await m.makeSession(owner),'createShow',{record})).status,200);assert.equal((await api(await m.makeSession(owner),'createShow',{record:{...record,id:crypto.randomUUID()}})).status,200);assert.equal(calendarWrites,before+1);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_payments WHERE show_id=?').get(result.body.show.id).n,1);await update(result.body.show.id,150000000,{},await m.makeSession(owner));assert.equal((await api(await m.makeSession(owner),'createShow',{record})).body.show.sale,150000000);assert.equal((await api(await m.makeSession(owner),'createShow',{record:{...record,sale:1}})).status,409);const agenda=await m.readAgenda('2026-10');assert.ok(agenda.events.some(e=>e.id===raw.id&&e.title===record.event.title));assert.ok(sql.prepare('SELECT sequence FROM jac_crm_exports WHERE payment_id=?').get(sql.prepare('SELECT id FROM jac_crm_payments WHERE show_id=?').get(result.body.show.id).id));});
test('crear show sin primer abono admite administrador jac y eventos de todo el día',async()=>{const record=creationRecord({event:{title:'Concierto manual ficticio',allDay:true,start:'2026-10-27',end:'2026-10-28',location:'',description:''}}),r=await api(await m.makeSession(delegate),'createShow',{record});assert.equal(r.status,200,r.body.error);assert.equal(r.body.show.showDate,'2026-10-27');assert.equal(r.body.show.paid,0);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_payments WHERE show_id=?').get(r.body.show.id).n,0);assert.equal(createdEvents.get('jac'+record.id.replaceAll('-','')).end.date,'2026-10-28');});
test('fallo de adjunto después de Calendar conserva evento y permite completar abono sin duplicados',async()=>{const record=creationRecord({event:{title:'ARMENIA · Creación con reintento',allDay:true,start:'2026-10-28',end:'2026-10-29',location:'',description:''},firstPayment:{amount:1000000,paymentDate:'2026-10-14',note:'',files:[{filename:'Reintento.pdf',data:proof}]}}),before=calendarWrites;putHook=async()=>{throw Error('Fallo ficticio R2');};let r;try{r=await api(await m.makeSession(owner),'createShow',{record});}finally{putHook=null;}assert.equal(r.status,502);assert.match(r.body.error,/show ya está creado/);assert.equal(calendarWrites,before+1);const row=sql.prepare('SELECT * FROM jac_crm_creations WHERE id=?').get(record.id);assert.equal(row.status,'account_ready');assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_payments WHERE show_id=?').get(row.show_id).n,0);r=await api(await m.makeSession(owner),'createShow',{record});assert.equal(r.status,200,r.body.error);assert.equal(r.body.show.paid,1000000);assert.equal(calendarWrites,before+1);});
test('respuesta perdida de Calendar y cambio de revisión conservan ID; sesión revocada impide nuevas escrituras',async()=>{const record=creationRecord({event:{title:'MANIZALES · Respuesta ficticia perdida',allDay:true,start:'2026-10-29',end:'2026-10-30',location:'',description:''}}),before=calendarWrites;googleHook=async(url,options)=>{if(url.pathname.endsWith('/events')&&options.method==='POST'){const raw={...JSON.parse(options.body),etag:'\"lost\"'};createdEvents.set(raw.id,raw);calendarWrites++;throw TypeError('Respuesta ficticia perdida');}return null;};try{assert.equal((await api(await m.makeSession(owner),'createShow',{record})).status,502);}finally{googleHook=null;}sql.prepare("UPDATE payroll_calendar SET version=version+1 WHERE id='jac'").run();const retried=await api(await m.makeSession(owner),'createShow',{record});assert.equal(retried.status,200,retried.body.error);assert.equal(calendarWrites,before+1);const token=await m.makeSession(delegate),next=creationRecord({revision:2,event:{title:'NEIVA · Sesión revocada ficticia',allDay:true,start:'2026-10-30',end:'2026-10-31',location:'',description:''}});googleHook=async url=>{if(url.pathname.includes('/calendarList/'))await m.revokeSession(token);return null;};try{assert.equal((await api(token,'createShow',{record:next})).status,403);}finally{googleHook=null;}assert.equal(calendarWrites,before+1);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_shows WHERE title=?').get(next.event.title).n,0);});

test('revocar sesión después de enviar a Google impide publicar la cuenta y el abono en D1/R2',async()=>{const token=await m.makeSession(delegate),record=creationRecord({revision:2,event:{title:'IBAGUE · Revocación tras envío ficticio',allDay:true,start:'2026-10-31',end:'2026-11-01',location:'',description:''},firstPayment:{amount:1000,paymentDate:'2026-10-14',note:'',files:[{filename:'Privado.pdf',data:proof}]}}),before=objects.size,writesBefore=calendarWrites;googleHook=async(url,options)=>{if(url.pathname.endsWith('/events')&&options.method==='POST')await m.revokeSession(token);return null;};try{assert.equal((await api(token,'createShow',{record})).status,403);}finally{googleHook=null;}assert.equal(calendarWrites,writesBefore+1);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_shows WHERE title=?').get(record.event.title).n,0);assert.equal(objects.size,before);assert.equal(sql.prepare('SELECT status FROM jac_crm_creations WHERE id=?').get(record.id).status,'pending');});

