test('borrado externo confirmado retira show y Agenda sin borrar abonos, PDF, hoja o nómina; listado viejo no lo resucita',async()=>{const f=await deletionFixture('borrado externo',true),raw=createdEvents.get(f.eventId),p=sql.prepare('SELECT id FROM jac_crm_payments WHERE show_id=?').get(f.show.id),detail=await api(f.token,undefined,{},'/api/crm?payment='+p.id),file=detail.body.payments[0].files[0].id,payroll=await m.readPayroll(),filesBefore=objects.size;createdEvents.delete(f.eventId);assert.equal((await api(f.token,'syncCalendar',{month:'2026-10'})).status,200);assert.equal(showState(f),'deleted');assert.ok(!(await api(f.token)).body.shows.some(s=>s.id===f.show.id));assert.ok(!(await m.readAgenda('2026-10')).events.some(e=>e.id===f.eventId));assert.equal((await api(f.token,undefined,{},'/api/crm/file?id='+p.id+'&file='+file)).status,200);assert.equal(objects.size,filesBefore);assert.deepEqual(await m.readPayroll(),payroll);assert.ok(sql.prepare('SELECT * FROM jac_crm_exports WHERE payment_id=?').get(p.id));createdEvents.set(f.eventId,raw);await api(f.token,'syncCalendar',{month:'2026-10'});assert.equal(showState(f),'deleted');createdEvents.delete(f.eventId);assert.equal((await api(f.token,'createShow',{record:f.record})).status,409);assert.equal((await update(f.show.id,1,{},f.token)).status,409);assert.equal((await api(f.token,'addPayment',{record:payment(f.show.id,1)})).status,400);});
test('un evento movido fuera del mes se actualiza por ID y no se confunde con borrado',async()=>{const f=await deletionFixture('movido a diciembre'),raw=createdEvents.get(f.eventId);createdEvents.set(f.eventId,{...raw,start:{date:'2026-12-18'},end:{date:'2026-12-19'},etag:'"moved"'});googleHook=async url=>url.pathname.endsWith('/events')?Response.json({items:[...createdEvents.values()].filter(e=>e.id!==f.eventId)}):null;try{assert.equal((await api(f.token,'syncCalendar',{month:'2026-10'})).status,200);}finally{googleHook=null;}const show=sql.prepare('SELECT * FROM jac_crm_shows WHERE id=?').get(f.show.id);assert.equal(show.source_state,'present');assert.equal(show.show_date,'2026-12-18');assert.equal(show.sale_cents,14000000000);});
test('Google cancelado confirma borrado; 403, 500 o respuesta inválida no eliminan datos',async()=>{for(const status of [403,500,'invalid','cancelled']){const f=await deletionFixture('estado '+status),raw=createdEvents.get(f.eventId);googleHook=async url=>{if(url.pathname.endsWith('/events'))return Response.json({items:[...createdEvents.values()].filter(e=>e.id!==f.eventId)});if(url.pathname.endsWith('/events/'+f.eventId))return status==='invalid'?Response.json({id:f.eventId}):status==='cancelled'?Response.json({id:f.eventId,status:'cancelled'}):Response.json({error:{}},{status});return null;};try{const r=await api(f.token,'syncCalendar',{month:'2026-10'});assert.equal(r.status,status==='cancelled'?200:502);assert.equal(showState(f),status==='cancelled'?'deleted':'present');}finally{googleHook=null;if(status==='cancelled')createdEvents.delete(f.eventId);else createdEvents.set(f.eventId,raw);}}});
test('eliminar desde CRM exige administrador, origen y versión, revalida ETag y no elimina cambios ajenos',async()=>{const f=await deletionFixture('conflicto protegido'),record=await prepareDelete(f);for(const user of [reader,alex])assert.equal((await api(await m.makeSession(user),'deleteShow',{record})).status,403);assert.equal((await api(f.token,'deleteShow',{record},'/api/crm','https://otro.invalid')).status,403);createdEvents.get(f.eventId).etag='"changed-after-confirmation"';const r=await api(f.token,'deleteShow',{record});assert.equal(r.status,409);assert.equal(showState(f),'present');assert.ok(createdEvents.has(f.eventId));const fresh=await prepareDelete(f);googleHook=async(url,options)=>url.pathname.endsWith('/events/'+f.eventId)&&options.method==='DELETE'?Response.json({error:{}},{status:412}):null;try{assert.equal((await api(f.token,'deleteShow',{record:fresh})).status,409);}finally{googleHook=null;}assert.equal(showState(f),'present');assert.ok(createdEvents.has(f.eventId));});
test('administrador jac elimina el evento exacto con If-Match, conserva finanzas y reintento es idempotente',async()=>{const f=await deletionFixture('borrado jac',true),token=await m.makeSession(delegate),record=await prepareDelete(f,token),before=objects.size;assert.equal((await api(token,'deleteShow',{record})).status,200);assert.equal(showState(f),'deleted');assert.ok(!createdEvents.has(f.eventId));assert.equal(objects.size,before);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_payments WHERE show_id=?').get(f.show.id).n,1);const deletes=calls.filter(c=>c.options.method==='DELETE').length;assert.equal((await api(token,'deleteShow',{record})).status,200);assert.equal(calls.filter(c=>c.options.method==='DELETE').length,deletes);assert.ok(!(await api(token)).body.shows.some(s=>s.id===f.show.id));});
test('DELETE con respuesta perdida mantiene intento estable, bloquea pagos y se recupera sin resucitar evento',async()=>{const f=await deletionFixture('respuesta perdida DELETE',true),record=await prepareDelete(f);googleHook=async(url,options)=>{if(url.pathname.endsWith('/events/'+f.eventId)&&options.method==='DELETE'){createdEvents.delete(f.eventId);throw TypeError('Respuesta ficticia perdida');}return null;};try{assert.equal((await api(f.token,'deleteShow',{record})).status,502);}finally{googleHook=null;}assert.equal(showState(f),'deleting');const pay=sql.prepare('SELECT id,version FROM jac_crm_payments WHERE show_id=?').get(f.show.id);assert.equal((await api(f.token,'voidPayment',{record:{id:pay.id,version:pay.version,reason:'No debe alterar el intento pendiente'}})).status,409);assert.deepEqual(await prepareDelete(f),record);assert.equal((await api(f.token,'addPayment',{record:payment(f.show.id,1)})).status,400);assert.equal((await api(f.token,'createShow',{record:f.record})).status,409);assert.equal((await api(f.token,'deleteShow',{record})).status,200);assert.equal(showState(f),'deleted');});
test('revocación antes de DELETE impide envío, después conserva intención para reconciliar sin permiso obsoleto',async()=>{for(const after of [false,true]){const f=await deletionFixture('revocación '+after),record=await prepareDelete(f),token=await m.makeSession(delegate),sentBefore=calls.filter(c=>c.options.method==='DELETE').length;googleHook=async(url,options)=>{if(url.pathname.endsWith('/events/'+f.eventId)&&((after&&options.method==='DELETE')||(!after&&options.method!=='DELETE')))await m.revokeSession(token);return null;};try{const r=await api(token,'deleteShow',{record});assert.ok([403,409].includes(r.status),r.body.error);}finally{googleHook=null;}assert.equal(calls.filter(c=>c.options.method==='DELETE').length,sentBefore+(after?1:0));assert.equal(showState(f),'deleting');assert.equal((await api(f.token,'deleteShow',{record})).status,200);assert.equal(showState(f),'deleted');}});
test('cambio de conexión no borra otro calendario y permite reconfirmar intención con misma selección renovada',async()=>{const f=await deletionFixture('revisión renovada'),record=await prepareDelete(f);googleHook=async(url,options)=>{if(url.pathname.endsWith('/events/'+f.eventId)&&options.method==='DELETE')throw TypeError('Fallo ficticio antes de enviar');return null;};try{assert.equal((await api(f.token,'deleteShow',{record})).status,502);}finally{googleHook=null;}sql.prepare("UPDATE payroll_calendar SET version=version+1 WHERE id='jac'").run();assert.equal((await api(f.token,'deleteShow',{record})).status,409);const renewed=await prepareDelete(f);assert.notEqual(renewed.id,record.id);assert.equal(renewed.revision,record.revision+1);assert.equal((await api(f.token,'deleteShow',{record:renewed})).status,200);});

test('comprobantes usan consecutivo por show, extensión real, reintento sin consumir número y cargas concurrentes distintas',async()=>{
 const token=await m.makeSession(owner),record=creationRecord({revision:sql.prepare("SELECT version FROM payroll_calendar WHERE id='jac'").get().version,event:{title:'Copacabana',allDay:true,start:'2026-10-28',end:'2026-10-29',location:'',description:''},firstPayment:{amount:1000,paymentDate:'2026-10-14',note:'',files:[{filename:'Banco original.jpg',data:proof},{filename:'Imagen original.pdf',data:Buffer.from([137,80,78,71,13,10,26,10,1,2,3]).toString('base64')}]}}),r=await api(token,'createShow',{record});assert.equal(r.status,200,r.body.error);const id=r.body.show.id;
 const names=()=>sql.prepare("SELECT a.filename FROM jac_notice_attachments a JOIN jac_crm_payments p ON a.notice_id='crm-payment:'||p.id WHERE p.show_id=? AND a.state='ready' ORDER BY a.rowid").all(id).map(x=>x.filename);
 assert.deepEqual(names(),['Copacabana-1.pdf','Copacabana-2.png']);assert.equal(r.body.show.receiptNext,3);assert.equal((await api(token,'createShow',{record})).status,200);assert.equal(sql.prepare('SELECT receipt_sequence FROM jac_crm_shows WHERE id=?').get(id).receipt_sequence,2);
 const pay1={...payment(id,2000),files:[{filename:'mal nombrado.pdf',data:Buffer.from([255,216,255,1,2,3]).toString('base64')}]},pay2={...payment(id,3000),files:[{filename:'otro original.pdf',data:Buffer.from('%PDF-1.4\nFICTITIOUS DIFFERENT RECEIPT\n%%EOF').toString('base64')}]};
 const [a,b]=await Promise.all([api(token,'addPayment',{record:pay1}),api(token,'addPayment',{record:pay2})]);assert.equal(a.status,200,a.body.error);assert.equal(b.status,200,b.body.error);assert.deepEqual(names().map(n=>Number(n.match(/-(\d+)\./)[1])).sort((a,b)=>a-b),[1,2,3,4]);assert.equal(new Set(names()).size,4);
 assert.equal((await api(token,'addPayment',{record:pay1})).status,200);assert.equal(names().length,4);assert.equal(sql.prepare('SELECT receipt_sequence FROM jac_crm_shows WHERE id=?').get(id).receipt_sequence,4);
 const direct=await api(token,undefined,{},'/api/crm/file?id='+pay1.id);assert.equal(direct.status,200);assert.equal(direct.headers.get('content-type'),'image/jpeg');assert.match(direct.headers.get('content-disposition'),/^inline;.*Copacabana-[34]\.jpg/);assert.deepEqual(direct.body,new Uint8Array([255,216,255,1,2,3]));assert.match(direct.headers.get('cache-control'),/no-store/);assert.equal((await api(await m.makeSession(reader),undefined,{},'/api/crm/file?id='+pay1.id)).status,403);
 const before=sql.prepare('SELECT receipt_sequence FROM jac_crm_shows WHERE id=?').get(id).receipt_sequence,pending=payment(id,4000);putHook=async()=>{throw Error('R2 ficticio sin respuesta');};try{assert.equal((await api(token,'addPayment',{record:pending})).status,502);}finally{putHook=null;}assert.equal(sql.prepare('SELECT receipt_sequence FROM jac_crm_shows WHERE id=?').get(id).receipt_sequence,before);assert.equal((await api(token,'addPayment',{record:pending})).status,200);assert.ok(names().includes('Copacabana-5.pdf'));
});
test('migración conserva nombres anteriores y continúa consecutivo incluyendo anulados, y reencola enlaces de Sheets sin crear filas',async()=>{
 const old=new DatabaseSync(':memory:');try{for(const f of(await readdir('drizzle')).filter(f=>f.endsWith('.sql')&&f<'0019').sort())old.exec(await readFile('drizzle/'+f,'utf8'));
 const show=crypto.randomUUID(),pay=crypto.randomUUID();old.prepare("INSERT INTO jac_crm_shows(id,calendar_id,event_id,title,municipality,show_date,created_at,updated_at) VALUES(?,'fixture','fixture','Copacabana','Copacabana','2026-10-28','fixture','fixture')").run(show);old.prepare("INSERT INTO jac_crm_payments(id,show_id,amount_cents,payment_date,hash,actor_id,upload_token,created_at,status) VALUES(?,?,100,'2026-10-14','hash','fixture','fixture','fixture','voided')").run(pay,show);old.prepare('INSERT INTO jac_crm_exports(payment_id,synced_version) VALUES(?,1)').run(pay);
 for(let i=0;i<2;i++)old.prepare("INSERT INTO jac_notice_attachments(id,notice_id,file_key,filename,mime_type,size,expires_at,state) VALUES(?,?,?,?,'application/pdf',10,'fixture','ready')").run(crypto.randomUUID(),'crm-payment:'+pay,'fixture-'+i,'Original-'+i+'.pdf');
 old.exec(await readFile('drizzle/0019_crm_receipt_sequence.sql','utf8'));assert.equal(old.prepare('SELECT receipt_sequence FROM jac_crm_shows').get().receipt_sequence,2);assert.deepEqual(old.prepare('SELECT filename FROM jac_notice_attachments ORDER BY rowid').all().map(r=>r.filename),['Original-0.pdf','Original-1.pdf']);const jobs=old.prepare('SELECT * FROM jac_crm_exports').all();assert.equal(jobs.length,1);assert.equal(jobs[0].version,2);assert.equal(jobs[0].synced_version,1);
 }finally{old.close();}
});
test('enlace directo conserva 401 para API y redirige navegación sin sesión a login con retorno al archivo privado',async()=>{
 globalThis.__crmHeaders=new Headers({host:'crm.example.invalid'});const id=crypto.randomUUID();let response=await m.receipt.GET(new Request(base+'/api/crm/file?id='+id));assert.equal(response.status,401);response=await m.receipt.GET(new Request(base+'/api/crm/file?id='+id,{headers:{'sec-fetch-mode':'navigate'}}));assert.equal(response.status,303);const url=new URL(response.headers.get('location'),base);assert.equal(url.pathname,'/acceso');assert.equal(url.searchParams.get('returnTo'),'/api/crm/file?id='+id);assert.match(response.headers.get('cache-control'),/no-store/);
});

// Creation and edits share the same automatic contact resolution on the server.
const contactRecord=(name,label=name)=>creationRecord({revision:sql.prepare("SELECT version FROM payroll_calendar WHERE id='jac'").get().version,entrepreneur:name,event:{title:'PEREIRA · Contacto ficticio '+label,allDay:true,start:'2026-10-28',end:'2026-10-29',location:'',description:''}});
test('nombre nuevo crea ficha reutilizable, aparece en Empresarios y conserva el mismo vínculo al reintentar',async()=>{
 const token=await m.makeSession(owner),record=contactRecord('  Organizador   nuevo ficticio  '),before=calendarWrites;
 const first=await api(token,'createShow',{record});assert.equal(first.status,200,first.body.error);const id=first.body.show.contactId;assert.ok(id);
 const directory=await api(token,undefined,{},'/api/crm?view=contacts');assert.ok(directory.body.contacts.some(c=>c.id===id&&c.name==='Organizador nuevo ficticio'));
 const detail=await api(token,undefined,{},'/api/crm?view=contact&id='+id);assert.equal(detail.body.shows[0].id,first.body.show.id);assert.equal(detail.body.contact.email,'');assert.equal(detail.body.contact.phone,'');
 for(const retry of [record,{...record,id:crypto.randomUUID()}]){const r=await api(token,'createShow',{record:retry});assert.equal(r.status,200,r.body.error);assert.equal(r.body.show.contactId,id);}
 assert.equal(calendarWrites,before+1);assert.equal(sql.prepare('SELECT count(*) n FROM jac_crm_contacts WHERE id=?').get(id).n,1);
 assert.equal(sql.prepare("SELECT count(*) n FROM jac_crm_audit WHERE show_id=? AND action='contact-created-from-show'").get('contact:'+id).n,1);
});
